    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Sustaining Quality Accreditation In Hospitals: A Systematic Review With Narrative Synthesis",
      "reason": "The title includes supplementary information on the analysis method: 'with narrative synthesis'."
    }
