{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The calculated effect sizes included standardized mean difference and odds ratio with their respective 95% CI.",
      "reason": "Effect measures (SMD, OR) were prespecified for the planned meta-analysis, and Hedges' g with 95% CI was reported for the three quantitative studies (text_8), but the meta-analysis was not performed and effect measures for the narrative synthesis outcomes (direction of effect, vote-counting) are not specified per outcome."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No thresholds or ranges for interpreting effect sizes (or their rationale) are reported; the I² > 50% threshold concerns heterogeneity model choice, not effect size interpretation."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although convertibility to SMD is mentioned as an inclusion criterion for pooling, no methods for re-expressing synthesized results using another effect measure are described."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The choice of effect measure (SMD, OR, Hedges' g) is not justified; only the random-effects model choice is justified due to anticipated heterogeneity."
    }
  ],
  "confidence": 82
}

